    t->edges[t->edge_cnt].to = v;
    t->edges[t->edge_cnt].next = t->head[u];
    t->head[u] = t->edge_cnt++;

    t->edges[t->edge_cnt].to = u;
    t->edges[t->edge_cnt].next = t->head[v];
    t->head[v] = t->edge_cnt++;
}

int queue[MAX_NODES];
int dist[MAX_NODES];
int parent[MAX_NODES];
int path[MAX_NODES];

int bfs(Tree *t, int start, int record_parent) {
    for (int i = 1; i <= t->n; i++) {
        dist[i] = -1;
        if (record_parent) parent[i] = 0;
    }

    int head = 0, tail = 0;
    queue[tail++] = start;
    dist[start] = 0;

    int farthest_node = start;

    while (head < tail) {
        int u = queue[head++];
        if (dist[u] > dist[farthest_node]) {
            farthest_node = u;
        }

        for (int e = t->head[u]; e != -1; e = t->edges[e].next) {
            int v = t->edges[e].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (record_parent) parent[v] = u;
                queue[tail++] = v;
            }
        }
    }

